extern "C" int strcmp(const char *, const char *);

class stringx
{
protected:
  char *chars;
  void *my_buf;

public:
  const char *c_str() const { return chars; }
};

template<class T>
struct my_allocator
{
};

template<class T, class Alloc>
struct vector
{
  T *start;
  T *finish;
  T *end_of_storage;
};

class animation_interface
{
public:
  struct s_t_s_t_r
  {
    bool operator()(const stringx &s1, const stringx &s2) const
    {
      return strcmp(s1.c_str(), s2.c_str()) < 0;
    }
  };

  struct anim_info
  {
    float percent;
    stringx anim;
    int damage;
    float recover_time;
    float recover_var;
    int flags;
  };
};

typedef vector<animation_interface::anim_info,
               my_allocator<animation_interface::anim_info> > anim_vector;

template<class A, class B>
struct pair
{
  A first;
  B second;

  pair(const A &a, const B &b) : first(a), second(b) {}
};

typedef pair<const stringx, anim_vector> value_type;

struct node
{
  int color;
  node *parent;
  node *left;
  node *right;
  value_type value;
};

struct iterator
{
  node *current;

  iterator(node *x) : current(x) {}

  iterator &operator--()
  {
    if (current->color == 0 && current->parent->parent == current)
      current = current->right;
    else if (current->left != 0)
    {
      node *y = current->left;
      while (y->right != 0)
        y = y->right;
      current = y;
    }
    else
    {
      node *y = current->parent;
      while (current == y->left)
      {
        current = y;
        y = y->parent;
      }
      current = y;
    }
    return *this;
  }
};

struct tree
{
  node *header;
  unsigned int node_count;
  animation_interface::s_t_s_t_r key_compare;
};

