pair<iterator, bool> insert_unique(tree *self, const value_type &value)
{
  node *y = self->header;
  node *x = self->header->parent;
  bool comp = true;
  while (x != 0)
  {
    y = x;
    comp = self->key_compare(value.first, x->value.first);
    x = comp ? x->left : x->right;
  }
  iterator j(y);
  if (comp)
  {
    if (j.current == self->header->left)
      return pair<iterator, bool>(tree_insert(self, x, y, value), true);
    else
      --j;
  }
  if (self->key_compare(j.current->value.first, value.first))
    return pair<iterator, bool>(tree_insert(self, x, y, value), true);
  return pair<iterator, bool>(j, false);
}
